var mapDiv = "mapa";
var idioma = "cas";
function getParam(param){

		 var src = String( window.location.href ).split('?')[1];
		 var vrs = src.split('&');
		 
		 for (var x = 0, c = vrs.length; x < c; x++) {
		 		 if (vrs[x].indexOf(param + '=') != -1){
		 		 		 return decodeURI( vrs[x].split('=')[1] );
		 		 		 break;
		 		 };
		 };
}
